head.b:skin:
    :root {
      --forest: #103c2d;
      --green: #147a55;
      --orange: #e78022;
      --ink: #1b2c25;
      --muted: #687a71;
      --paper: #ffffff;
      --canvas: #f3f6f2;
      --line: #e5ece7;
      --shadow: 0 24px 54px -36px rgba(16, 60, 45, .55);
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      color: var(--ink);
      background:
        radial-gradient(ellipse at 86% 8%, rgba(226, 239, 229, .9), transparent 34rem),
        linear-gradient(145deg, #f8faf8, var(--canvas) 58%, #edf3ee);
      font: 16px/1.6 "Segoe UI", Arial, sans-serif;
    }
    a { color: inherit; }
    .container { width: min(1120px, calc(100% - 40px)); margin: 0 auto; }
    .site-header {
      position: sticky;
      z-index: 5;
      top: 0;
      border-bottom: 1px solid rgba(229, 236, 231, .8);
      background: rgba(248, 250, 248, .92);
      backdrop-filter: blur(14px);
    }
    .header-inner {
      display: flex;
      min-height: 82px;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }
    .brand {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      text-decoration: none;
    }
    .brand-mark {
      display: grid;
      width: 48px;
      height: 48px;
      place-items: center;
      border-radius: 15px;
      color: white;
      background: linear-gradient(145deg, var(--orange), #c74742);
      box-shadow: 0 9px 18px rgba(199, 71, 66, .22);
      font-size: 19px;
      font-weight: 900;
      letter-spacing: -.08em;
    }
    .brand-copy { display: grid; line-height: 1.15; }
    .brand-copy strong { color: var(--forest); font-size: 20px; letter-spacing: -.04em; }
    .brand-copy small {
      margin-top: 5px;
      color: var(--orange);
      font-size: 9px;
      font-weight: 800;
      letter-spacing: .12em;
    }
    .main-nav { display: flex; align-items: center; gap: 26px; }
    .main-nav a {
      color: #53645a;
      font-size: 14px;
      font-weight: 700;
      text-decoration: none;
    }
    .main-nav a:hover { color: var(--green); }
    .button {
      display: inline-flex;
      min-height: 46px;
      align-items: center;
      justify-content: center;
      padding: 0 20px;
      border: 0;
      border-radius: 13px;
      color: white !important;
      background: var(--green);
      box-shadow: 0 12px 24px -16px rgba(20, 122, 85, .9);
      font-size: 14px;
      font-weight: 800;
      text-decoration: none;
      transition: transform .18s ease, background .18s ease;
    }
    .button:hover { transform: translateY(-2px); background: #106544; }
    .hero { padding: 82px 0 74px; }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.05fr .95fr;
      align-items: center;
      gap: 54px;
    }
    .eyebrow {
      margin: 0 0 12px;
      color: var(--green);
      font-size: 11px;
      font-weight: 900;
      letter-spacing: .18em;
    }
    h1, h2, h3, p { margin-top: 0; }
    h1 {
      max-width: 650px;
      margin-bottom: 18px;
      color: var(--forest);
      font-size: clamp(42px, 6vw, 68px);
      line-height: 1.02;
      letter-spacing: -.065em;
    }
    .hero-copy > p:not(.eyebrow) {
      max-width: 540px;
      margin-bottom: 28px;
      color: var(--muted);
      font-size: 18px;
    }
    .hero-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 14px; }
    .text-link { color: var(--forest); font-size: 14px; font-weight: 800; text-decoration: none; }
    .text-link:hover { color: var(--green); }
    .visual-card {
      position: relative;
      overflow: hidden;
      min-height: 350px;
      padding: 30px;
      border: 1px solid rgba(255,255,255,.92);
      border-radius: 28px;
      background: linear-gradient(150deg, #174b37, #103c2d 68%, #0d3024);
      box-shadow: 0 36px 70px -40px rgba(16,60,45,.8);
      color: white;
      transform: perspective(900px) rotateY(-5deg) rotateX(2deg);
    }
    .visual-card:after {
      position: absolute;
      right: -80px;
      bottom: -155px;
      width: 330px;
      height: 330px;
      border: 1px solid rgba(255,255,255,.14);
      border-radius: 50%;
      box-shadow: 0 0 0 32px rgba(255,255,255,.035), 0 0 0 70px rgba(255,255,255,.025);
      content: "";
    }
    .visual-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
    .visual-label { color: #d3e6dc; font-size: 12px; font-weight: 700; }
    .live-pill {
      padding: 6px 10px;
      border: 1px solid rgba(195,232,210,.25);
      border-radius: 99px;
      color: #d7f0df;
      background: rgba(99,190,133,.13);
      font-size: 11px;
      font-weight: 800;
    }
    .visual-total { margin: 36px 0 4px; color: #c9ddd1; font-size: 13px; }
    .visual-amount { margin: 0; font-size: 42px; font-weight: 800; letter-spacing: -.05em; }
    .visual-caption { margin: 0; color: #b7cfc0; font-size: 12px; }
    .visual-rule { height: 1px; margin: 26px 0; background: rgba(255,255,255,.15); }
    .visual-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .visual-row + .visual-row { margin-top: 18px; }
    .visual-person { display: flex; align-items: center; gap: 11px; }
    .avatar {
      display: grid;
      width: 37px;
      height: 37px;
      place-items: center;
      border-radius: 12px;
      color: #f7dcc0;
      background: rgba(231,128,34,.2);
      font-size: 13px;
      font-weight: 900;
    }
    .visual-person strong, .visual-person small { display: block; }
    .visual-person strong { font-size: 13px; }
    .visual-person small { color: #b7cfc0; font-size: 11px; }
    .visual-value { color: #f5c27b; font-size: 13px; font-weight: 800; }
    .visual-footnote { position: absolute; right: 24px; bottom: 18px; color: #bfd1c5; font-size: 10px; }
    .trust-row {
      display: flex;
      flex-wrap: wrap;
      gap: 10px 24px;
      margin-top: 38px;
      color: #617168;
      font-size: 12px;
      font-weight: 700;
    }
    .trust-row span:before { margin-right: 7px; color: var(--green); content: "✓"; font-weight: 900; }
    .section { padding: 76px 0; }
    .section-soft { background: rgba(255,255,255,.62); }
    .section-heading { max-width: 660px; margin: 0 auto 38px; text-align: center; }
    .section-heading h2 {
      margin-bottom: 10px;
      color: var(--forest);
      font-size: clamp(29px, 4vw, 42px);
      line-height: 1.12;
      letter-spacing: -.05em;
    }
    .section-heading p:last-child { margin-bottom: 0; color: var(--muted); }
    .feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
    .feature-card {
      padding: 25px;
      border: 1px solid var(--line);
      border-radius: 20px;
      background: var(--paper);
      box-shadow: var(--shadow);
    }
    .feature-icon {
      display: grid;
      width: 44px;
      height: 44px;
      margin-bottom: 18px;
      place-items: center;
      border-radius: 14px;
      color: var(--green);
      background: #e8f3ec;
      font-size: 19px;
      font-weight: 900;
    }
    .feature-card h3 { margin-bottom: 7px; color: var(--forest); font-size: 17px; }
    .feature-card p { margin-bottom: 0; color: var(--muted); font-size: 14px; }
    .steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
    .step { position: relative; padding: 4px 8px; }
    .step-number {
      display: inline-grid;
      width: 42px;
      height: 42px;
      margin-bottom: 16px;
      place-items: center;
      border: 1px solid #d5e6da;
      border-radius: 14px;
      color: var(--green);
      background: #edf5ef;
      font-weight: 900;
    }
    .step h3 { margin-bottom: 7px; color: var(--forest); font-size: 17px; }
    .step p { margin-bottom: 0; color: var(--muted); font-size: 14px; }
    .cta-panel {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 28px;
      padding: 38px;
      border-radius: 26px;
      color: white;
      background: linear-gradient(120deg, #103c2d, #1a6244);
      box-shadow: var(--shadow);
    }
    .cta-panel h2 { margin-bottom: 7px; font-size: clamp(25px, 4vw, 36px); letter-spacing: -.04em; }
    .cta-panel p { margin-bottom: 0; color: #d2e4d8; }
    .cta-panel .button { flex: 0 0 auto; color: var(--forest) !important; background: white; }
    .blog-area { padding: 58px 0 74px; }
    .blog-area h2 { color: var(--forest); font-size: 30px; letter-spacing: -.04em; }
    .blog-posts .widget { margin: 18px 0; }
    .blog-posts .post-outer {
      margin: 16px 0;
      padding: 24px;
      border: 1px solid var(--line);
      border-radius: 18px;
      background: white;
      box-shadow: var(--shadow);
    }
    .blog-posts h3, .blog-posts h2 { color: var(--forest); }
    .blog-posts a { color: var(--green); }
    .footer { padding: 30px 0; color: #d6e4da; background: #0c3023; }
    .footer-inner { display: flex; justify-content: space-between; gap: 20px; }
    .footer p { margin: 0; font-size: 12px; }
    .footer a { color: white; font-weight: 700; text-decoration: none; }
    @media (max-width: 800px) {
      .hero { padding: 56px 0; }
      .hero-grid { grid-template-columns: 1fr; gap: 36px; }
      .visual-card { min-height: 330px; transform: none; }
      .feature-grid { grid-template-columns: 1fr 1fr; }
      .main-nav { gap: 14px; }
      .main-nav .nav-contact { display: none; }
    }
    @media (max-width: 560px) {
      .container { width: min(100% - 28px, 1120px); }
      .header-inner { min-height: 70px; gap: 10px; }
      .brand-mark { width: 42px; height: 42px; }
      .brand-copy strong { font-size: 17px; }
      .brand-copy small { font-size: 8px; }
      .main-nav { gap: 12px; }
      .main-nav a { font-size: 12px; }
      .main-nav .button { min-height: 39px; padding: 0 12px; font-size: 12px; }
      .main-nav .nav-services { display: none; }
      h1 { font-size: 43px; }
      .hero-copy > p:not(.eyebrow) { font-size: 16px; }
      .visual-card { min-height: 310px; padding: 22px; }
      .visual-amount { font-size: 36px; }
      .feature-grid, .steps { grid-template-columns: 1fr; }
      .section { padding: 56px 0; }
      .cta-panel { align-items: flex-start; flex-direction: column; padding: 27px; }
      .footer-inner { flex-direction: column; }
    }
